for lab,items in extra.items():
 for task,values in zip(d[lab],items):
  task.update(question_model=values[0],client_answer=values[1],transfer_model=values[2],new_brief=values[3],independent_model=values[4])
  task['scaffolds']={'A2':['I notice ___.','I recommend ___ because ___.','Could you confirm ___?'],'B1':['Describe the visible detail or project problem.','Give one recommendation and its reason.','Ask one useful follow-up question.'],'B2':['Acknowledge the client’s goal before recommending.','Explain a tradeoff or qualify an interpretation.','Confirm a decision, requirement, or review step.']}
